<?php
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__.'/../Config/mikrotik.php'; require_once __DIR__.'/../library/routeros_api.class.php';
try{$cfg=new MikroTikConfig();$id=(int)($_GET['router_id']??0);if($id){require_once __DIR__.'/../Config/database.php';$pdo=(new Database())->connect();$s=$pdo->prepare('SELECT * FROM router WHERE id=? LIMIT 1');$s->execute([$id]);$router=$s->fetch(PDO::FETCH_ASSOC);}else{$router=$cfg->getRouter();}if(!$router){echo json_encode(['status'=>'offline','message'=>'Router tidak tersedia']);exit;}$api=new RouterosAPI();$api->debug=false;if(!$api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){echo json_encode(['status'=>'offline','message'=>'Router tidak dapat terhubung']);exit;}$servers=$api->comm('/ip/dhcp-server/print');$leases=$api->comm('/ip/dhcp-server/lease/print');$api->disconnect();$ss=[];foreach($servers as $x){$ss[]=['name'=>$x['name']??'-','interface'=>$x['interface']??'-','address_pool'=>$x['address-pool']??'-','disabled'=>isset($x['disabled'])];}$ls=[];foreach($leases as $x){$ls[]=['id'=>$x['.id']??'','address'=>$x['address']??'-','mac'=>$x['mac-address']??'-','hostname'=>$x['host-name']??'-','server'=>$x['server']??'-','status'=>$x['status']??(isset($x['dynamic'])?'dynamic':'static'),'dynamic'=>isset($x['dynamic']),'disabled'=>isset($x['disabled']),'expires'=>$x['expires-after']??'-'];}echo json_encode(['status'=>'online','router'=>$router['router_name'],'router_id'=>(int)$router['id'],'servers'=>$ss,'leases'=>$ls]);}catch(Throwable $e){http_response_code(500);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}